func metricsDiff(metricsDiff map[string]interface{}, k string, val1, val2 interface{}) {
	mv1, okNum1 := toFloat64(val1)
	mv2, okNum2 := toFloat64(val2)
	var v1, v2 interface{}
	if okNum1 {
		v1 = mv1
	} else if val1 != nil {
		v1 = val1
	} else {
		v1 = nil
	}
	if okNum2 {
		v2 = mv2
	} else if val2 != nil {
		v2 = val2
	} else {
		v2 = nil
	}
	if !okNum1 || !okNum2 {
		metricsDiff[k] = map[string]interface{}{"v1": v1, "v2": v2, "delta": nil, "pct_change": nil}
		return
	}
	delta := mv2 - mv1
	var pct interface{}
	if mv1 == 0 {
		pct = nil
	} else {
		pct = delta / math.Abs(mv1) * 100
	}
	metricsDiff[k] = map[string]interface{}{"v1": v1, "v2": v2, "delta": delta, "pct_change": pct}
}

